<script lang="ts">
  import{onDestroy,untrack}from'svelte';
  import ProfileCanvas from './ProfileCanvas.svelte';
  import ProfileProcessingEditor from './ProfileProcessingEditor.svelte';
  import ProfileVirtualEditor from './ProfileVirtualEditor.svelte';
  import ProfileDesktopEditor from './ProfileDesktopEditor.svelte';
  import {desktopPreset,DESKTOP_PRESETS,type DesktopPreset,type ProfileDesktopOutput}from'./profile-desktop';
  import {graphSetDesktop}from'./profile-graph';
  import ProfileInputLearning from './ProfileInputLearning.svelte';
  import ProfileCompanionEditor from './ProfileCompanionEditor.svelte';
  import {ProfileLearningController}from'./profile-learning-controller';
  import type{ProfileLearningClient}from'./profile-learning';
  import {canvasNodes,portContractLabel,type CanvasNode} from './profile-canvas';
  import {graphAssignResource,graphBypassProcessing,graphConnect,graphConnectionError,graphDisconnect,graphFreshId,graphInsertProcessing,graphInventorySignature,graphPort,graphPorts,graphPublicationCapability,graphRemoveNode,graphRemovePort,graphReorderProcessing,graphSelectProviderPort,graphSetProcessing,graphSetRuntimeOverride,graphSetVirtual,graphSetVisibility,type ProfileGraphDraft}from'./profile-graph';
  import {PROCESSING_PRESETS,processingActionPack,processingNodeError,processingTemplate,type ProcessingPreset}from'./profile-processing';
  import {ProfilePortBrowser}from'./profile-port-browser';
  import type{CompilationSummary,CompileDiagnostic,ProfileCompilerClient}from'./profile-compilation';
  import type{DeepReadonly,ProfileDocument,ProfileLocalAssignment,ProfilePortContract,ProfileProcessingNode,ProfileVirtualOutput}from'./profiles';
  import type{ObservedResourcePort,ProfileInventoryClient,ResourceDetails,ResourceSummary}from'./profile-inventory';
  import type{GameId}from'./games';
  import type{ProfileCompanionAuthoringClient}from'./profile-companion-authoring';
  let{document,assignments,inventory,inventoryClient,compilerClient,learningClient,companionClient,editorContext='',active=true,runtimeIdle=false,inventoryRevision=0,readOnly=false,selectedId=$bindable(''),change,openGameSettings,undo,redo,canUndo=false,canRedo=false,undoLabel='',redoLabel=''}:{
    document:DeepReadonly<ProfileDocument>;assignments:readonly DeepReadonly<ProfileLocalAssignment>[];inventory:readonly DeepReadonly<ResourceSummary>[];inventoryClient:Pick<ProfileInventoryClient,'inspect'>;compilerClient?:Pick<ProfileCompilerClient,'compile'|'inspect'>;inventoryRevision?:number;readOnly?:boolean;selectedId?:string;
    change:(draft:ProfileGraphDraft,label:string)=>void;openGameSettings?:(gameId:GameId,returnState?:unknown)=>void;undo?:()=>void;redo?:()=>void;canUndo?:boolean;canRedo?:boolean;undoLabel?:string;redoLabel?:string;
    companionClient?:Pick<ProfileCompanionAuthoringClient,'catalogue'|'inspect'>;learningClient?:Pick<ProfileLearningClient,'start'|'status'|'cancel'>;editorContext?:string;active?:boolean;runtimeIdle?:boolean;
  }=$props();
  const copy=<T,>(value:T):T=>JSON.parse(JSON.stringify(value));
  let message=$state(''),routeOpen=$state(false),fromNode=$state(''),fromPort=$state(''),toNode=$state(''),toPort=$state(''),editingRoute=$state(''),highlighted=$state<string[]>([]),preset=$state<ProcessingPreset>('identity'),chainOrder=$state<string[]>([]);
  let desktopChoice=$state<DesktopPreset>('key-hold');
  let assignmentFor=$state(''),assignmentSource=$state(''),assignmentPage=$state.raw<DeepReadonly<ResourceDetails>|null>(null),assignmentBusy=$state(false),assignmentError=$state(''),selectedMappings=$state.raw<Record<string,DeepReadonly<ObservedResourcePort>>>({}),assignmentEpoch=0;
  let policyInspectorOpen=$state(untrack(()=>!assignments.some(assignment=>assignment.resourceId===selectedId)));
  const assignmentBrowser=new ProfilePortBrowser(untrack(()=>inventoryClient));
  const learning=untrack(()=>learningClient)?new ProfileLearningController(untrack(()=>learningClient)!):null;
  const nodes=$derived(canvasNodes(document,assignments,inventory)),selected=$derived(nodes.find(node=>node.id===selectedId));
  const graph=$derived({document,assignments});
  const sourcePorts=$derived(graphPorts(document,fromNode).filter(port=>port.direction==='output')),targetPorts=$derived(graphPorts(document,toNode).filter(port=>port.direction==='input'));
  const sourceContract=$derived(sourcePorts.find(port=>port.id===fromPort)?.contract);
  const targetAction=$derived(targetPorts.find(port=>port.id===toPort)?.contract);
  const connectionError=$derived(fromNode&&fromPort&&toNode&&toPort?graphConnectionError(document,{nodeId:fromNode,portId:fromPort},{nodeId:toNode,portId:toPort},editingRoute||undefined):'Select both exact ports.');
  const actionPorts=$derived(nodes.flatMap(node=>graphPorts(document,node.id).filter(port=>port.contract.delivery==='action').map(port=>({label:`${node.name} / ${port.name}`,contract:port.contract}))));
  const assignmentResources=$derived(inventory.filter(resource=>selected?.resource?.kind===(resource.resourceType==='game-integration'?'game':resource.resourceType==='companion'?'companion':'device')));
  const mappingOptions=$derived.by(()=>{const ports=[...(assignmentPage?.ports??[]),...Object.values(selectedMappings)],seen=new Set<string>();return ports.filter(port=>{const key=optionKey(port);if(seen.has(key))return false;seen.add(key);return true;});});
  $effect(()=>{const id=selectedId;if(id!==assignmentFor){assignmentFor=id;policyInspectorOpen=!assignments.some(assignment=>assignment.resourceId===id);assignmentSource='';assignmentPage=null;selectedMappings={};assignmentError='';assignmentBusy=false;assignmentEpoch++;assignmentBrowser.clear();}});
  onDestroy(()=>{assignmentEpoch++;assignmentBrowser.clear();learning?.dispose();});
  function apply(edit:()=>ProfileGraphDraft,label:string){if(readOnly)return;message='';try{change(edit(),label);}catch(error){message=error instanceof Error?error.message:String(error);}}
  function source(id:string){fromNode=id;fromPort='';editingRoute='';routeOpen=true;message='';}
  function destination(id:string){toNode=id;toPort='';routeOpen=true;message='';}
  function connectBlocks(from:string,to:string){source(from);destination(to);}
  function connect(){apply(()=>graphConnect(graph,{nodeId:fromNode,portId:fromPort},{nodeId:toNode,portId:toPort},editingRoute||undefined),editingRoute?'Edit exact route':'Connect exact ports');}
  function editRoute(id:string){const binding=document.bindings.find(binding=>binding.id===id);if(!binding)return;editingRoute=id;fromNode=binding.from.nodeId;fromPort=binding.from.portId;toNode=binding.to.nodeId;toPort=binding.to.portId;routeOpen=true;highlighted=[id];}
  function selectPort(nodeId:string,port:DeepReadonly<ObservedResourcePort>){const assignment=assignments.find(assignment=>assignment.resourceId===nodeId);if(!assignment)return;apply(()=>graphSelectProviderPort(graph,nodeId,assignment.sourceId,port),'Select exact provider port');}
  function addVirtual(){const id=graphFreshId(document,'virtual');apply(()=>graphSetVirtual(graph,{id,name:'Virtual controller',required:false,layout:{buttons:['button-1','button-2','button-3','button-4'],axes:[],hats:[]}}),'Add virtual controller');selectedId=id;}
  function addDesktop(){const id=graphFreshId(document,'desktop');apply(()=>{const preset=desktopPreset(desktopChoice,id);let next=graphSetDesktop(graph,preset.output);for(const node of preset.nodes)next=graphSetProcessing(next,node);for(const route of preset.routes)next=graphConnect(next,route.from,route.to);return next;},'Add desktop endpoint and visible preset');selectedId=id;}
  function updateDesktop(output:ProfileDesktopOutput){apply(()=>graphSetDesktop(graph,output),'Edit typed desktop actions');}
  function addProcessing(bindingId?:string){
    apply(()=>{const binding=document.bindings.find(binding=>binding.id===bindingId),selectedPort=sourcePorts.find(port=>port.id===fromPort)??(selected?graphPorts(document,selected.id).find(port=>port.direction==='output'):undefined),input=binding?graphPort(document,binding.from)?.contract:selectedPort?.contract,target=binding?graphPort(document,binding.to)?.contract:targetAction;
      const node=processingTemplate(preset,graphFreshId(document,'transform'),input,target);const next=binding?graphInsertProcessing(graph,binding.id,node,node.inputs[0]?.id??'',node.outputs[0].id):graphSetProcessing(graph,node);selectedId=node.id;return next;},bindingId?'Insert visible transformation':'Add visible transformation');
  }
  function actionPack(mode:'action-pack'|'set-on-change'){if(targetAction?.delivery!=='action')return;apply(()=>{const input=sourcePorts.find(port=>port.id===fromPort)?.contract,node=processingActionPack(graphFreshId(document,'transform'),targetAction,mode,input?.delivery==='event'?input:undefined),next=graphSetProcessing(graph,node);selectedId=node.id;return next;},'Add explicit action arguments');}
  function updateProcessing(node:ProfileProcessingNode){apply(()=>{const error=processingNodeError(node);if(error)throw new Error(error);return graphSetProcessing(graph,node);},'Edit visible transformation');}
  function updateVirtual(output:Omit<ProfileVirtualOutput,'ports'>){apply(()=>graphSetVirtual(graph,output),'Edit virtual controller layout');}
  function removeNode(id:string){apply(()=>graphRemoveNode(graph,id),'Remove block and its routes');selectedId='';}
  function optionKey(port:DeepReadonly<ObservedResourcePort>):string{return JSON.stringify([port.descriptor.id,port.contractHash]);}
  function chooseMapping(portId:string,key:string){const observed=mappingOptions.find(port=>optionKey(port)===key);const next={...selectedMappings};if(observed)next[portId]=observed;else delete next[portId];selectedMappings=next;}
  async function browseAssignment(operation:'open'|'next'|'previous'){
    const epoch=++assignmentEpoch,resourceId=assignmentSource;assignmentBusy=true;assignmentError='';if(operation==='open'){assignmentPage=null;selectedMappings={};}
    try{const page=operation==='open'?await assignmentBrowser.open(resourceId):operation==='next'?await assignmentBrowser.next():await assignmentBrowser.previous();if(epoch===assignmentEpoch&&page)assignmentPage=page;}
    catch(error){if(epoch===assignmentEpoch)assignmentError=error instanceof Error?error.message:String(error);}finally{if(epoch===assignmentEpoch)assignmentBusy=false;}
  }
  function assignResource(){const source=inventory.find(resource=>resource.id===assignmentSource),resource=selected?.resource;if(!source||!resource)return;apply(()=>graphAssignResource(graph,resource.id,source,resource.ports.flatMap(port=>selectedMappings[port.id]?[{profilePortId:port.id,observed:selectedMappings[port.id]}]:[])),'Assign exact resource and ports');}
  function resourcePolicy(node:CanvasNode,key:'name'|'required',value:string|boolean){apply(()=>{const next=copy(graph) as ProfileGraphDraft,resource=next.document.resources.find(resource=>resource.id===node.id)!;if(key==='name'&&typeof value==='string')resource.name=value;if(key==='required'&&typeof value==='boolean')resource.required=value;return next;},'Edit resource policy');}
  function publicationPolicy(node:CanvasNode,value:string){apply(()=>{if(!['configured','enabled','disabled'].includes(value))throw new Error('Choose an explicit controller publication policy.');const capability=graphPublicationCapability(node.observation);if(value!=='configured'&&capability.status==='unsupported')throw new Error(capability.message);return graphSetRuntimeOverride(graph,node.id,value==='configured'?null:value==='enabled');},'Edit controller publication policy');}
</script>

<section class="routing-workspace" aria-label="Explicit profile routing editor">
  <div class="routing-toolbar"><button class="secondary-button" disabled={readOnly} onclick={()=>{routeOpen=!routeOpen;editingRoute='';}}>Connect exact ports</button><button class="secondary-button" disabled={readOnly||document.virtualOutputs.length>=8} onclick={addVirtual}>Add virtual controller</button><label>Visible transformation<select aria-label="Visible transformation" bind:value={preset}>{#each PROCESSING_PRESETS as [kind,label]}<option value={kind}>{label}</option>{/each}</select></label><button class="secondary-button" disabled={readOnly} onclick={()=>addProcessing()}>Add transformation</button><div class="history-tools"><button class="text-button" title={undoLabel} disabled={readOnly||!canUndo} onclick={undo}>Undo</button><button class="text-button" title={redoLabel} disabled={readOnly||!canRedo} onclick={redo}>Redo</button></div></div>
  {#if message}<p class="routing-error" role="alert">{message}</p>{/if}
  <div class="routing-toolbar desktop-tools" aria-label="Desktop output presets"><label>Keyboard and mouse preset<select aria-label="Keyboard and mouse preset" bind:value={desktopChoice}>{#each DESKTOP_PRESETS as [kind,label]}<option value={kind}>{label}</option>{/each}</select></label><button class="secondary-button" disabled={readOnly||!!document.desktopOutputs?.length} onclick={addDesktop}>Add keyboard and mouse</button><p>One desktop endpoint per profile. Presets add visible processing; connect exact source ports explicitly. No virtual controller is required.</p></div>
  {#if routeOpen}<section class="route-composer panel" aria-label="Exact connection editor"><div class="route-heading"><h3>{editingRoute?'Edit explicit signal route':'Choose a concrete signal route'}</h3><button class="text-button" onclick={()=>routeOpen=false}>Close connection editor</button></div><p>Each route carries one selected output to one input. Reverse feedback is a separate route. Conversion and argument packing are visible blocks.</p><div class="connection-fields"><label>Source block<select aria-label="Source block" value={fromNode} onchange={event=>{fromNode=event.currentTarget.value;fromPort='';}}><option value="">Choose source</option>{#each nodes.filter(node=>node.kind!=='virtual') as node (node.id)}<option value={node.id}>{node.name}</option>{/each}</select></label><label>Exact source output<select aria-label="Exact source output" value={fromPort} onchange={event=>fromPort=event.currentTarget.value}><option value="">Choose output port</option>{#each sourcePorts as port (port.id)}<option value={port.id}>{port.name} · {port.id}</option>{/each}</select></label><label>Destination block<select aria-label="Destination block" value={toNode} onchange={event=>{toNode=event.currentTarget.value;toPort='';}}><option value="">Choose destination</option>{#each nodes as node (node.id)}<option value={node.id}>{node.name}</option>{/each}</select></label><label>Exact destination input / action<select aria-label="Exact destination input / action" value={toPort} onchange={event=>toPort=event.currentTarget.value}><option value="">Choose input or action</option>{#each targetPorts as port (port.id)}<option value={port.id}>{port.name} · {port.id}</option>{/each}</select></label></div>
    {#if sourceContract}<p>{portContractLabel(sourceContract)}</p>{/if}{#if targetAction}<p>{portContractLabel(targetAction)}</p>{/if}<p class:connection-problem={!!connectionError} role="status">{connectionError||'Compatible exact port contracts.'}</p><button class="primary-button" disabled={readOnly||!!connectionError} onclick={connect}>{editingRoute?'Update exact route':'Create exact route'}</button>
    {#if targetAction?.delivery==='action'}<div class="argument-actions"><button class="secondary-button" disabled={readOnly} onclick={()=>actionPack('action-pack')}>Add event-triggered argument pack</button>{#if targetAction.semantics==='setter'}<button class="secondary-button" disabled={readOnly} onclick={()=>actionPack('set-on-change')}>Add setter on argument change</button>{/if}<p>Map each named argument into the new node, then connect its invocation output to this action. No argument or trigger is inferred.</p></div>{/if}
  </section>{/if}
  <ProfileCanvas companionAuthoring {document} {assignments} {inventory} {inventoryClient} {readOnly} bind:selectedId {openGameSettings} change={(next,label)=>change({document:next,assignments:copy(assignments) as ProfileLocalAssignment[]},label??'Edit canvas layout')} {connectBlocks} connectionFrom={source} connectionTo={destination} selectProviderPort={selectPort} removeProviderPort={(nodeId,portId)=>apply(()=>graphRemovePort(graph,nodeId,portId),'Remove selected port and routes')} highlightedEdges={highlighted} diagnostics={[]} {undo} {redo}>
    {#snippet inspector(node)}
      <fieldset class="authoring-inspector" disabled={readOnly}>
        {#if node.resource}<details bind:open={policyInspectorOpen}><summary>Resource assignment and policy</summary><label>Block label<input value={node.resource.name} maxlength="80" onchange={event=>resourcePolicy(node,'name',event.currentTarget.value)}/></label><label class="check"><input type="checkbox" checked={node.resource.required} onchange={event=>resourcePolicy(node,'required',event.currentTarget.checked)}/> Required resource</label>
          {#if node.resource.kind==='device'}<label>Game visibility intent<select value={document.visibility.find(intent=>intent.resourceId===node.id)?.mode??'visible'} onchange={event=>apply(()=>graphSetVisibility(graph,node.id,event.currentTarget.value==='hidden-while-active'?'hidden-while-active':'visible'),'Edit visibility intent')}><option value="visible">Visible</option><option value="hidden-while-active">Hidden while profile is active</option></select></label>{/if}
          {#if node.resource.kind==='device'}{@const publication=graphPublicationCapability(node.observation)}<label>Controller publication policy<select value={document.overrides.some(policy=>policy.resourceId===node.id)?document.overrides.find(policy=>policy.resourceId===node.id)!.enabled?'enabled':'disabled':'configured'} onchange={event=>publicationPolicy(node,event.currentTarget.value)}><option value="configured">Keep configured</option><option value="enabled" disabled={publication.status==='unsupported'}>Enable while active</option><option value="disabled" disabled={publication.status==='unsupported'}>Disable while active</option></select></label><p class="publication-status" role="status">{publication.message}{#if publication.configuredEnabled!==null} Configured controller publication: {publication.configuredEnabled?'enabled':'disabled'}.{/if}</p><p class="publication-warning">Enabling or disabling publication can change USB controller collections, require a USB reconnect and require game rebinding. This policy does not save device flash. Controller publication and game hiding are separate.</p>{/if}
          <p>{node.assignment?'Assigned locally; replacing it requires an exact match for every selected port.':'Unassigned. Choose a matching inventory resource; copied graphs are never resolved by name.'}</p><label>Inventory resource<select value={assignmentSource} onchange={event=>{assignmentSource=event.currentTarget.value;if(assignmentSource)void browseAssignment('open');}}><option value="">Choose resource explicitly</option>{#each assignmentResources as resource (resource.id)}<option value={resource.id}>{resource.name} · {resource.availability}</option>{/each}</select></label>
          {#if assignmentBusy}<p role="status">Loading provider port page…</p>{/if}{#if assignmentError}<p class="routing-error" role="status">{assignmentError}</p>{/if}
          {#if assignmentSource}{#each node.resource.ports as port (port.id)}<label>Logical {port.id} → provider port<select value={selectedMappings[port.id]?optionKey(selectedMappings[port.id]):''} onchange={event=>chooseMapping(port.id,event.currentTarget.value)}><option value="">Choose exact matching port</option>{#each mappingOptions.filter(observed=>observed.descriptor.direction===port.direction) as observed (optionKey(observed))}<option value={optionKey(observed)}>{observed.descriptor.name} · {observed.descriptor.id} {observed.current?'':'(cached)'}</option>{/each}</select><small>{portContractLabel(port.contract)}</small></label>{/each}{#if assignmentPage}<p>{assignmentPage.offset+1}–{assignmentPage.offset+assignmentPage.ports.length} of {assignmentPage.total} cached contracts</p><div class="small-actions"><button class="text-button" disabled={assignmentBusy||!assignmentBrowser.hasPrevious} onclick={()=>browseAssignment('previous')}>Previous ports</button><button class="text-button" disabled={assignmentBusy||!assignmentBrowser.hasNext} onclick={()=>browseAssignment('next')}>Next ports</button></div>{/if}<button class="secondary-button" disabled={node.resource.ports.some(port=>!selectedMappings[port.id])||assignmentBusy} onclick={assignResource}>Assign resource and exact ports</button>{/if}
        </details>{/if}
        {#if node.processing}<ProfileProcessingEditor node={node.processing} change={updateProcessing} actions={actionPorts}/>{#if node.processing.inputs.length===1&&node.processing.outputs.length===1}<button class="text-button" onclick={()=>apply(()=>graphBypassProcessing(graph,node.id),'Remove transformation and join compatible route')}>Remove transformation and join compatible route</button>{/if}{/if}
        {#if node.virtual}<ProfileVirtualEditor output={node.virtual} change={updateVirtual}/>{/if}
        {#if node.desktop}<ProfileDesktopEditor output={node.desktop} change={updateDesktop}/>{/if}
        <p class="remove-help">Removing this block also removes {document.bindings.filter(binding=>binding.from.nodeId===node.id||binding.to.nodeId===node.id).length} exact routes.</p><button class="text-button" onclick={()=>removeNode(node.id)}>Remove block and its routes</button>
      </fieldset>
      {#if node.resource?.kind==='companion'}<ProfileCompanionEditor {graph} {inventory} resourceId={node.id} {readOnly} {active} client={companionClient} {change}/>{/if}
      {#if learning&&node.resource&&node.assignment&&node.observation?.resourceType==='host-controller'}<ProfileInputLearning controller={learning} resource={node.observation} context={`${editorContext}/${node.id}/${node.assignment.sourceId}`} {active} disabled={readOnly} {runtimeIdle} choose={port=>selectPort(node.id,port)}/>{/if}
    {/snippet}
  </ProfileCanvas>
  <section class="bindings-panel panel" aria-label="Exact bindings table"><div class="route-heading"><h3>Exact signal bindings · {document.bindings.length}</h3><button class="text-button" onclick={()=>highlighted=[]}>Clear route highlight</button></div><p>Each row is one directed edge in this graph. Choose a row to inspect or retarget exact ports; insert a visible transformation using the selected preset.</p><div class="bindings-scroll"><table><thead><tr><th>Route</th><th>Source output</th><th>Destination input / action</th><th>Graph editing</th></tr></thead><tbody>{#each document.bindings as binding (binding.id)}<tr class:highlighted={highlighted.includes(binding.id)}><td><button class="text-button" onclick={()=>editRoute(binding.id)}>{binding.id}</button></td><td><button class="endpoint-button" onclick={()=>selectedId=binding.from.nodeId}>{nodes.find(node=>node.id===binding.from.nodeId)?.name??binding.from.nodeId}<code>{binding.from.portId}</code></button></td><td><button class="endpoint-button" onclick={()=>selectedId=binding.to.nodeId}>{nodes.find(node=>node.id===binding.to.nodeId)?.name??binding.to.nodeId}<code>{binding.to.portId}</code></button></td><td><div class="small-actions"><button class="text-button" disabled={readOnly} onclick={()=>editRoute(binding.id)}>Edit ports</button><button class="text-button" disabled={readOnly||preset==='constant'} onclick={()=>addProcessing(binding.id)}>Insert {PROCESSING_PRESETS.find(([kind])=>kind===preset)![1]}</button><button class="text-button" disabled={readOnly} onclick={()=>apply(()=>graphDisconnect(graph,binding.id),'Remove exact route')}>Remove</button></div></td></tr>{:else}<tr><td colspan="4">No routes yet. Select provider ports, then connect exact outputs and inputs.</td></tr>{/each}</tbody></table></div>
    {#if document.processingNodes.length>=2}<details><summary>Reorder a linear transformation chain</summary><p>Select a connected chain in the desired order. Each selected block must have one input and one output, without branches. Incompatible orders are rejected.</p><div class="chain-options">{#each document.processingNodes.filter(node=>node.inputs.length===1&&node.outputs.length===1) as node (node.id)}<button class="secondary-button" class:chosen={chainOrder.includes(node.id)} disabled={readOnly} onclick={()=>chainOrder=chainOrder.includes(node.id)?chainOrder.filter(id=>id!==node.id):[...chainOrder,node.id]}>{chainOrder.includes(node.id)?`${chainOrder.indexOf(node.id)+1}. `:''}{node.name}</button>{/each}</div><button class="secondary-button" disabled={readOnly||chainOrder.length<2} onclick={()=>apply(()=>graphReorderProcessing(graph,chainOrder),'Reorder visible transformation chain')}>Use selected chain order</button></details>{/if}
  </section>
</section>
<style>
  .routing-toolbar{display:flex;align-items:end;gap:10px;flex-wrap:wrap;margin:17px 0}.routing-toolbar label{display:grid;gap:6px;font-size:9px;color:var(--muted)}.routing-workspace button{font-size:10px}.routing-workspace select,.routing-workspace input:not([type="checkbox"]){background:var(--input-bg);color:var(--text);border:1px solid var(--line);border-radius:5px;padding:8px;font-size:10px;min-width:0;width:100%;box-sizing:border-box}.history-tools{margin-left:auto;display:flex;gap:12px}.route-composer,.bindings-panel{padding:18px;margin:16px 0}.route-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}h3{font-size:13px;color:var(--soft)}p{font-size:10px;color:var(--muted);line-height:1.8;margin:10px 0}.connection-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:15px 0}label{font-size:9px;color:var(--muted);display:grid;gap:7px}.connection-problem,.routing-error{color:#d3a078}.routing-error{padding:12px;border:1px solid #ad875440;border-radius:6px;font-size:10px;line-height:1.8}.argument-actions{margin-top:15px;border-top:1px solid var(--line);padding-top:14px;display:flex;gap:9px;flex-wrap:wrap}.argument-actions p{flex-basis:100%}.authoring-inspector{border:0;margin:0;padding:0;min-width:0}.authoring-inspector label{margin:12px 0}.authoring-inspector details{margin:16px 0;border-top:1px solid var(--line);padding-top:14px}.authoring-inspector summary{font-size:10px;color:var(--soft);cursor:pointer}.authoring-inspector small{font-size:9px;line-height:1.8}.check{display:flex;align-items:center;gap:8px}.small-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.bindings-scroll{overflow:auto;max-height:460px}table{width:100%;border-collapse:collapse;font-size:10px;text-align:left}th{font-size:9px;font-weight:400;color:var(--muted);padding:12px;border-bottom:1px solid var(--line)}td{padding:12px;border-bottom:1px solid var(--faint-line);color:var(--soft);vertical-align:top}tr.highlighted{background:var(--accent-bg)}.endpoint-button{display:grid;gap:7px;background:none;color:var(--soft);padding:0;text-align:left;max-width:220px;overflow-wrap:anywhere}.endpoint-button code{font-size:9px;color:var(--muted)}.bindings-panel details{margin-top:16px}.bindings-panel summary{font-size:10px;color:var(--soft);cursor:pointer}.chain-options{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.chain-options .chosen{border-color:var(--accent);color:var(--accent)}@media(max-width:700px){.connection-fields{grid-template-columns:1fr}.history-tools{margin-left:0}.route-heading{align-items:start;flex-direction:column}}
</style>
